const calendlyUrl = (() => {
  const params = new URLSearchParams({
    name: form.name,
    email: form.email,
    a1: form.company,
    a2: form.scenario,
    background_color: 'f2f2ee',
    text_color: '121212',
    primary_color: 'e0643a',
  })
  return `${CALENDLY_BASE}?${params.toString()}`
})()
